func smaller(a, b int) int {
	if a < b {
		return a
	}
	return b
}
func (plan *Plan) fee(seats int) int {
	if plan.perSeat {
		return plan.price * seats
	}
	return plan.price
}
func (plan *Plan) usageCharge(units int) int {
	for i, tier := range plan.tiers {
